import{_ as i,C as a,o as p,c as n,j as t,a as e,E as o,ah as r}from"./chunks/framework.BpF7DVZ1.js";const P=JSON.parse('{"title":"审批","description":"","frontmatter":{},"headers":[],"relativePath":"components/approval.md","filePath":"components/approval.md","lastUpdated":1788635489000}'),s={name:"components/approval.md"},h={id:"审批",tabindex:"-1"};function g(u,d,v,b,x,m){const l=a("Badge"),c=a("XhDemo");return p(),n("div",null,[t("h1",h,[d[0]||(d[0]=e("审批 ",-1)),o(l,{type:"info",text:"approval"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#审批","aria-label":'Permalink to "审批 <Badge type="info" text="approval" />"'},"​",-1))]),d[3]||(d[3]=r('<p>危险动作执行前的人在环闸门：批准、拒绝，超时按拒绝收口，可带勾选式的授权范围。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>Agent 要动真格之前（写文件、发请求、花钱）先问一句。</li><li>这次授权带范围：批准的同时要说清批的是哪几项。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是一句「确定吗」：用<a href="./popconfirm">气泡确认</a>。</li><li>判定结果不影响任何执行：那不是闸门，是一个提示。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><strong>超时一律按拒绝收口</strong>，且这条由机器结构保证、不靠调用方守规矩：判定的取值域只有 批准与拒绝，<code>expired</code> 只是显示态；通往批准的转移全机只有一条；到点事件只在待决态上 有转移，迟到的定时事件落地即静默丢弃。</li><li><strong>缺省不给默认超时值</strong>：替宿主定安全策略比不定更危险。时长非有限或非正数时一个计时器 都不起，停在待决——既不当 0ms 立刻到期，也绝不当成无限期放行。</li><li><strong>拒绝这条路永远走得通</strong>：机器这一层的拒绝不吃必选项、不吃任何闸门，超时、卸载兜底与 宿主的 <code>deny()</code> 入口都落得下去。人手按的那两条路（拒绝按钮与 Escape）另有一道挂起闸门： 判定在途时它们跟批准钮一起锁住，否则等待宿主回话的空窗里能按出第二条判定。</li><li>勾选与判定是原子的：批准的载荷带着「批的是哪几项」，不存在「已批准但范围还没同步」的窗口。</li><li>备注（<code>note</code>）与勾选同批取快照，随判定载荷一起发出；空着就不带这一格。 它不参与「必选项勾满了没有」的判断。</li><li><code>requestId</code> 变了即重入待决并按新时长重起计时；<strong>不替旧一轮补一次拒绝</strong>，旧结果由宿主自己作废。 重入时勾选与备注一并回到各自的默认值。</li><li>判定落定后 <code>result</code> 那一格才露出，语气随判定走（批准取成功档，拒绝与超时同取危险档）。 它对读屏隐藏：同一句话由播报区念一次就够。</li><li>两颗按钮住在 <code>actions</code> 那一行里，间距与对齐归库管，不必每个使用者自己写一个 flex 容器。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>勾选与判定是原子的：批准的载荷带着批的是哪几项，不存在「已批准但范围还没同步」的窗口</p>',10)),o(c,{src:"approval/01-basic"}),d[4]||(d[4]=t("h3",{id:"超时按拒绝收口",tabindex:"-1"},[e("超时按拒绝收口 "),t("a",{class:"header-anchor",href:"#超时按拒绝收口","aria-label":'Permalink to "超时按拒绝收口"'},"​")],-1)),d[5]||(d[5]=t("p",null,"缺省不给默认超时值：替宿主定安全策略比不定更危险。到点落成拒绝，expired 只是显示态",-1)),o(c,{src:"approval/02-timeout"}),d[6]||(d[6]=t("h3",{id:"附一句备注",tabindex:"-1"},[e("附一句备注 "),t("a",{class:"header-anchor",href:"#附一句备注","aria-label":'Permalink to "附一句备注"'},"​")],-1)),d[7]||(d[7]=t("p",null,"备注与勾选同批取快照，随判定载荷一起发出；空着就不带这一格，它不参与「必选项勾满了没有」的判断",-1)),o(c,{src:"approval/03-note"}),d[8]||(d[8]=t("h3",{id:"形态与尺寸",tabindex:"-1"},[e("形态与尺寸 "),t("a",{class:"header-anchor",href:"#形态与尺寸","aria-label":'Permalink to "形态与尺寸"'},"​")],-1)),d[9]||(d[9]=t("p",null,"variant 换这块闸门怎么与正文分开，size 换标题、条目与按钮的几何档；判定链一个字不动",-1)),o(c,{src:"approval/04-variant-size"}),d[10]||(d[10]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-approval&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhApprovalApproveTrigger</code> <code>XhApprovalDenyTrigger</code> <code>XhApprovalDescription</code> <code>XhApprovalFooter</code> <code>XhApprovalGroup</code> <code>XhApprovalItem</code> <code>XhApprovalItemIndicator</code> <code>XhApprovalItemText</code> <code>XhApprovalLiveRegion</code> <code>XhApprovalNote</code> <code>XhApprovalResult</code> <code>XhApprovalRoot</code> <code>XhApprovalTimer</code> <code>XhApprovalTitle</code></td></tr><tr><td>组合式函数</td><td><code>useApproval</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/approval.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;approval&quot;</code>：<strong><code>root</code></strong> · <code>title</code> · <code>description</code> · <code>live-region</code> · <code>group</code> · <code>item</code> · <code>item-indicator</code> · <code>item-text</code> · <code>note</code> · <code>timer</code> · <code>result</code> · <code>footer</code> · <strong><code>approve-trigger</code></strong> · <strong><code>deny-trigger</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>requestId</code></td><td><code>string</code></td><td></td><td>这一轮请求的身份。变了即重入待决，并按新时长重起计时。</td></tr><tr><td><code>status</code></td><td><code>ApprovalStatus</code></td><td></td><td>给定即受控。</td></tr><tr><td><code>defaultStatus</code></td><td><code>ApprovalStatus</code></td><td></td><td></td></tr><tr><td><code>timeoutMs</code></td><td><code>number</code></td><td></td><td>多久没人答就按拒绝收口。<strong>缺省不给默认值</strong>——替宿主定安全策略比不定更危险。 非有限值或非正数同样不起计时器，既不当 0ms 立刻到期，也绝不当成无限期放行。</td></tr><tr><td><code>scopes</code></td><td><code>readonly ApprovalScope[]</code></td><td></td><td></td></tr><tr><td><code>grantedScopes</code></td><td><code>readonly string[]</code></td><td></td><td></td></tr><tr><td><code>defaultGrantedScopes</code></td><td><code>readonly string[]</code></td><td></td><td></td></tr><tr><td><code>note</code></td><td><code>string</code></td><td></td><td>附在判定上的一句自由文本。给定即受控。 它只随判定载荷发出，不参与「必选项勾满了没有」的判断。</td></tr><tr><td><code>defaultNote</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>判定在途：只挡重复批准，不挡拒绝。</td></tr><tr><td><code>denyOnEscape</code></td><td><code>boolean</code></td><td></td><td>Escape 判为拒绝，默认开。</td></tr><tr><td><code>denyOnUnmount</code></td><td><code>boolean</code></td><td></td><td>卸载时若仍待决就按拒绝派发一次，<strong>默认关</strong>。 机理成立不等于默认值成立：列表换 key、路由切换、热更新任何一次重挂， 都会替用户发出他没做过的判定。</td></tr><tr><td><code>live</code></td><td><code>&#39;polite&#39; | &#39;assertive&#39;</code></td><td></td><td>播报档位，默认 polite。</td></tr><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td>形态：outline 描边（缺省档）、subtle 底色分区、ghost 无壳内联。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td></td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ApprovalTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onDecision</code></td><td><code>(details: ApprovalDecisionDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onGrantedScopesChange</code></td><td><code>(details: ApprovalScopesChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onNoteChange</code></td><td><code>(details: ApprovalNoteChangeDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>decision</code></td><td><code>ApprovalDecisionDetails</code></td><td>判定落定；detail 为 <code>{ requestId, decision, source, scopes }</code></td></tr><tr><td><code>granted-scopes-change</code></td><td><code>ApprovalScopesChangeDetails</code></td><td>勾选的授权项变化；detail 为 <code>{ value: string[] }</code></td></tr><tr><td><code>note-change</code></td><td><code>ApprovalNoteChangeDetails</code></td><td>备注变化；detail 为 <code>{ value: string }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhApprovalItem</code></td><td><code>default</code></td><td><code>ApprovalScopeSlotProps</code></td><td></td></tr><tr><td><code>XhApprovalRoot</code></td><td><code>default</code></td><td><code>ApprovalRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>state.get()</td></tr><tr><td><code>item</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-indicator</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>note</code></td><td>state.get()</td></tr><tr><td><code>timer</code></td><td>state.get()</td></tr><tr><td><code>result</code></td><td>state.get()</td></tr><tr><td><code>approve-trigger</code></td><td>state.get()</td></tr><tr><td><code>deny-trigger</code></td><td>state.get()</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>事件</strong>：<code>APPROVE</code> · <code>DENY</code> · <code>SCOPE.TOGGLE</code> · <code>SCOPE.SET</code> · <code>NOTE.SET</code> · <code>after.timeout</code> · <code>CONTROLLED.PENDING</code> · <code>CONTROLLED.APPROVE</code> · <code>CONTROLLED.DENY</code> · <code>CONTROLLED.EXPIRE</code> · <code>REQUEST.RESET</code></p><p><strong>判据</strong>：<code>isStatusControlled</code> · <code>canApprove</code> · <code>isEditable</code> · <code>canApproveControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useApproval</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>ApprovalStatus</code></td><td></td></tr><tr><td><code>settled</code></td><td><code>boolean</code></td><td>已经判过了：两颗按钮都收起出口。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>grantedScopes</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>note</code></td><td><code>string</code></td><td>备注里的文字；没写过是空串。</td></tr><tr><td><code>canApprove</code></td><td><code>boolean</code></td><td>必选项是不是都勾满了。</td></tr><tr><td><code>announcement</code></td><td><code>string</code></td><td>按 status 选出的那一句播报文本；announce 关掉时作者不渲那个部件即可。</td></tr><tr><td><code>approve</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>deny</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>setGrantedScopes</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>setNote</code></td><td><code>(next: string) =&gt; void</code></td><td></td></tr><tr><td><code>isScopeGranted</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(scope: ApprovalScope) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemIndicatorProps</code></td><td><code>(scope: ApprovalScope) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(scope: ApprovalScope) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getNoteProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td></td></tr><tr><td><code>getTimerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getResultProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getFooterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getApproveTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getDenyTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/checkbox/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在批准按钮上，待决、必选项已勾满、且不在挂起中</td><td>判为批准，载荷带上已勾选的授权项</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在拒绝按钮上，待决且不在挂起中</td><td>判为拒绝</td></tr><tr><td><code>Space</code></td><td>焦点在授权项上，待决且该项未禁用</td><td>勾选或取消该项。Enter 刻意不参与，与原生复选框一致</td></tr><tr><td><code>Escape</code></td><td>焦点在闸门内，待决、不在挂起中、且开着 denyOnEscape</td><td>判为拒绝。<strong>它不是「关闭」</strong>——本组件不提供不作答的出口</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>props.live</td></tr><tr><td><code>group</code></td><td><code>aria-label</code></td><td>translations?.scopes</td></tr><tr><td><code>group</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;checkbox&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>note</code></td><td><code>aria-label</code></td><td>translations?.note</td></tr><tr><td><code>timer</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>result</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>approve-trigger</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>approve-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>approve-trigger</code></td><td><code>aria-label</code></td><td>translations?.approve</td></tr><tr><td><code>deny-trigger</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>deny-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>deny-trigger</code></td><td><code>aria-label</code></td><td>translations?.deny</td></tr></tbody></table><ul><li>闸门是 <code>role=group</code>，由标题命名、由说明描述。</li><li>待决时批准键用 <code>aria-disabled</code> 而不是原生 <code>disabled</code>：保住可聚焦，让读屏念得到为什么按不动。</li><li>授权项是 <code>role=checkbox</code>，各占一个 Tab 停靠点，只认 <code>Space</code>——与原生复选框一致。</li><li>剩余时间与结果条都对读屏隐藏：逐秒变化的数字进活区会不停打断，判定结果由播报区念一次； 截止这件事同样在播报区里一次说清。</li><li>备注那一格取 <code>translations.note</code> 作可及名（缺省 <code>Note</code>），占位文字另走 <code>translations.notePlaceholder</code>。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/approval.css</code> 按部件选择：<code>[data-scope=&quot;approval&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>state.get()</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item</code></td><td><code>data-value</code></td><td>item.value</td></tr><tr><td><code>item-indicator</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-text</code></td><td><code>data-value</code></td><td>item.value</td></tr><tr><td><code>note</code></td><td><code>data-state</code></td><td>state.get()</td></tr><tr><td><code>timer</code></td><td><code>data-state</code></td><td>state.get()</td></tr><tr><td><code>result</code></td><td><code>data-state</code></td><td>state.get()</td></tr><tr><td><code>approve-trigger</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>approve-trigger</code></td><td><code>data-state</code></td><td>state.get()</td></tr><tr><td><code>deny-trigger</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>deny-trigger</code></td><td><code>data-state</code></td><td>state.get()</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-approval-action-font-size</code> · <code>--xh-approval-action-font-weight</code> · <code>--xh-approval-action-h</code> · <code>--xh-approval-action-px</code> · <code>--xh-approval-action-radius</code> · <code>--xh-approval-approve-bg</code> · <code>--xh-approval-approve-bg-hover</code> · <code>--xh-approval-approve-bg-off</code> · <code>--xh-approval-approve-fg</code> · <code>--xh-approval-approve-shadow</code> · <code>--xh-approval-bg</code> · <code>--xh-approval-border</code> · <code>--xh-approval-border-settled</code> · <code>--xh-approval-deny-bg</code> · <code>--xh-approval-deny-bg-hover</code> · <code>--xh-approval-deny-bg-off</code> · <code>--xh-approval-deny-border</code> · <code>--xh-approval-deny-border-off</code> · <code>--xh-approval-deny-fg</code> · <code>--xh-approval-description-fg</code> · <code>--xh-approval-description-font-size</code> · <code>--xh-approval-footer-gap</code> · <code>--xh-approval-gap</code> · <code>--xh-approval-group-gap</code> · <code>--xh-approval-icon-size</code> · <code>--xh-approval-indicator-bg-checked</code> · <code>--xh-approval-indicator-border</code> · <code>--xh-approval-indicator-border-checked</code> · <code>--xh-approval-indicator-fg</code> · <code>--xh-approval-indicator-radius</code> · <code>--xh-approval-indicator-size</code> · <code>--xh-approval-item-bg-hover</code> · <code>--xh-approval-item-font-size</code> · <code>--xh-approval-item-gap</code> · <code>--xh-approval-item-px</code> · <code>--xh-approval-item-py</code> · <code>--xh-approval-item-radius</code> · <code>--xh-approval-item-text-fg</code> · <code>--xh-approval-item-text-fg-checked</code> · <code>--xh-approval-loading-duration</code> · <code>--xh-approval-note-bg</code> · <code>--xh-approval-note-border</code> · <code>--xh-approval-note-fg</code> · <code>--xh-approval-note-font-size</code> · <code>--xh-approval-note-px</code> · <code>--xh-approval-note-py</code> · <code>--xh-approval-note-radius</code> · <code>--xh-approval-p</code> · <code>--xh-approval-radius</code> · <code>--xh-approval-result-bg</code> · <code>--xh-approval-result-bg-denied</code> · <code>--xh-approval-result-fg</code> · <code>--xh-approval-result-fg-denied</code> · <code>--xh-approval-result-font-size</code> · <code>--xh-approval-result-font-weight</code> · <code>--xh-approval-result-gap</code> · <code>--xh-approval-result-px</code> · <code>--xh-approval-result-py</code> · <code>--xh-approval-result-radius</code> · <code>--xh-approval-shadow</code> · <code>--xh-approval-timer-fg</code> · <code>--xh-approval-timer-font-size</code> · <code>--xh-approval-title-fg</code> · <code>--xh-approval-title-font-size</code> · <code>--xh-approval-title-font-weight</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-approval-in</code> · <code>xh-approval-result-in</code> · <code>xh-approval-rotate</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>border-color</code> · <code>box-shadow</code> · <code>color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>装进<a href="./tool-call">工具调用</a>的 <code>approval</code> 部件位：那一格常驻在开关与详情之间，不会被折叠藏起来。</li><li>要弹窗就一条一个<a href="./dialog">对话框</a>：<code>role=&quot;alertdialog&quot;</code>、关掉 <code>closeOnEscape</code>， 并把 <code>initialFocus</code> 设成本组件导出的 <code>APPROVAL_DENY_SELECTOR</code>—— 这样浮层只剩批准与拒绝两个出口，而 Escape 仍会冒泡到闸门上判拒绝。</li><li>剩余时间的跳字交给<a href="./timer">计时器</a>，判定权仍在本组件手里。 <strong>别把倒计时直接当 <code>timer</code> 那个节点渲</strong>：两套解剖打在同一节点上会互相盖， 让 <code>timer</code> 做外层容器、倒计时住在它里面。</li><li>要一次问好几件事：用<a href="./steps">步骤条</a>或<a href="./carousel">走马灯</a>串起若干个闸门，一步一个。 本组件是单发闸门，<code>data-state</code> 的四个值互斥，塞不下「第几题」。</li><li>要给用户「稍后再说」：那个入口归宿主，不归闸门。 常见做法是在 <code>onDecision</code> 之外自己留一条延后的路，或按上一条把闸门装进对话框—— 浮层里仍只有批准与拒绝两个出口。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>判定落定后两颗按钮都会禁用，浮层再无出口：<strong>宿主必须在判定回调里自己关闭浮层</strong>。</li><li>卸载即拒绝（<code>denyOnUnmount</code>）默认关着。开之前想清楚：列表换 key、路由切换、 热更新任何一次重挂，都会替用户发出他没做过的判定。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把超时做成「到点自动放行」：那等于把最危险的一档交给了沉默。</li><li>用一个可关闭的浮层承载它：关掉窗口既不是批准也不是拒绝，闸门就悬空了。</li></ul>',48))])}const q=i(s,[["render",g]]);export{P as __pageData,q as default};
